import React from 'react';

const CSS = `.hl{--hl-ink:var(--ui-primary,#0233BD);--hl-face:var(--sand-200,#F1EEE7);--hl-line:#9EA3AD;--hl-line2:#D2D5DB;--hl-text:#6E7480}
.hl *{vector-effect:non-scaling-stroke;stroke-linejoin:round;stroke-linecap:round}
.hl .ln{fill:var(--hl-face);stroke:var(--hl-line);stroke-width:1.1}
.hl .lo{fill:none;stroke:var(--hl-line);stroke-width:1.1}
.hl .lt{fill:none;stroke:var(--hl-line2);stroke-width:1}
.hl .dash{stroke-dasharray:3 4;stroke:var(--hl-line)}
.hl .fl{fill:var(--hl-face);stroke:none}
.hl .ink{fill:var(--hl-face);stroke:var(--hl-ink);stroke-width:1.5}
.hl .ko{fill:none;stroke:var(--hl-ink);stroke-width:1.5}
.hl .kf{fill:var(--hl-ink);stroke:none}
.hl .dot{fill:var(--hl-line);stroke:none}
.hl .bar{stroke:var(--hl-line);stroke-width:2.4}
.hl text{font-family:var(--font-mono,ui-monospace,SFMono-Regular,Menlo,monospace);font-size:8.5px;letter-spacing:.03em;stroke:none}
.hl .tx{fill:var(--hl-text)}
.hl .tk{fill:var(--hl-ink)}`;

function MachineFrame({ viewBox, label, accent, face, stillAt = 6, style, children }) {
  const ref = React.useRef(null);
  React.useEffect(() => {
    const svg = ref.current;
    if (!svg || !svg.pauseAnimations) return;
    const query = window.matchMedia('(prefers-reduced-motion: reduce)');
    const sync = () => {
      if (query.matches) {
        svg.setCurrentTime(stillAt);
        svg.pauseAnimations();
        return;
      }
      svg.unpauseAnimations();
    };
    sync();
    query.addEventListener('change', sync);
    return () => query.removeEventListener('change', sync);
  }, [stillAt]);
  const vars = { ...(accent ? { '--hl-ink': accent } : null), ...(face ? { '--hl-face': face } : null) };
  return <svg ref={ref} xmlns="http://www.w3.org/2000/svg" className="hl" viewBox={viewBox} role={label ? 'img' : undefined} aria-label={label} aria-hidden={label ? undefined : true} style={{ width: '100%', height: '100%', display: 'block', ...vars, ...style }}>
    <style>{CSS}</style>
    {children}
  </svg>;
}

